stage_a_raw:
{
  "decisions": [
    {
      "decision": "domain_of_flow_variables",
      "evidence": "Demand of Each Retail Store (in units) ... Supply Capacity of Each Distribution Center (in units)",
      "options": [
        "NonNegativeReals",
        "NonNegativeIntegers"
      ],
      "plausibility": [
        0.7,
        0.3
      ],
      "majority_option": "NonNegativeReals"
    },
    {
      "decision": "capacity_constraint_direction",
      "evidence": "Supply Capacity of Each Distribution Center (in units)",
      "options": [
        "sum_j x[i,j] <= capacity[i] * y[i]",
        "sum_j x[i,j] == capacity[i] * y[i]"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "sum_j x[i,j] <= capacity[i] * y[i]"
    },
    {
      "decision": "demand_constraint_direction",
      "evidence": "ensure that the demands of all retail stores are met",
      "options": [
        "sum_i x[i,j] == demand[j]",
        "sum_i x[i,j] >= demand[j]"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "sum_i x[i,j] == demand[j]"
    },
    {
      "decision": "objective_units_scale",
      "evidence": "Opening Costs for Each Distribution Center (in dollars) ... Transportation Cost Per Unit ... (in dollars)",
      "options": [
        "report total in dollars (opening costs as given, e.g. 151000)",
        "report total in thousands of dollars (opening costs divided by 1000)"
      ],
      "plausibility": [
        0.9,
        0.1
      ],
      "majority_option": "report total in dollars (opening costs as given, e.g. 151000)"
    },
    {
      "decision": "opening_cost_charged_once",
      "evidence": "Opening Costs for Each Distribution Center (in dollars)",
      "options": [
        "fixed charge opening_cost[i] * y[i] added once per opened center",
        "opening cost proportional to units shipped through center"
      ],
      "plausibility": [
        0.97,
        0.03
      ],
      "majority_option": "fixed charge opening_cost[i] * y[i] added once per opened center"
    },
    {
      "decision": "transport_cost_orientation",
      "evidence": "Transportation Cost Per Unit from Each Distribution Center to Retail Stores ... From Center 1: $5 to Store 1, $5 to Store 2, ...",
      "options": [
        "cost[(center, store)] with rows = centers, columns = stores",
        "cost[(store, center)] with rows = stores, columns = centers"
      ],
      "plausibility": [
        0.95,
        0.05
      ],
      "majority_option": "cost[(center, store)] with rows = centers, columns = stores"
    }
  ]
}
